            <tr><td className="px-3 py-2 text-xs">東北</td><td className="px-3 py-2 text-xs">宮城県</td><td className="px-3 py-2 text-xs">14件</td><td className="px-3 py-2 text-xs">大崎市の住宅・学校密集地における徘徊目撃</td></tr>
