            <tr><td className="px-3 py-2 text-xs">中部</td><td className="px-3 py-2 text-xs">長野県</td><td className="px-3 py-2 text-xs">15件</td><td className="px-3 py-2 text-xs">須坂市峰の原高原山林・各地区での出没</td></tr>
